class Solution:
    def kthDistinct(self, arr: List[str], k: int) -> str:
        hash_map = {}
        for string in arr:
            hash_map[string] = hash_map.get(string, 0) + 1
        for string in arr:
            if hash_map[string] == 1:
                k -= 1
                if k == 0:
                    return string
        return ""

import heapq

class Solution:
    def maxTwoEvents(self, events):
        events.sort()
        result = best = 0
        min_heap = []
        for left, right, v in events:
            heapq.heappush(min_heap, (right, v))
            while min_heap and min_heap[0][0] < left:
                best = max(best, heapq.heappop(min_heap)[1])
            result = max(result, best+v)
        return result

